function scoreCap(points){let n=0;while(n<5&&points>=thresholds[n+1])n++;return n}
function updateDifficulty(ok,assisted,questionLevel=state.stage){state.stage=Math.min(state.stage,scoreCap(state.points));if(assisted||(ok&&questionLevel<state.stage))return;state.recent.push(ok);state.recent=state.recent.slice(-8);state.stage=Math.min(state.stage,scoreCap(state.points));if(state.recent.length>=6&&state.recent.filter(Boolean).length/state.recent.length>=.75&&state.stage<scoreCap(state.points)){state.stage++;state.recent=[]}else if(state.recent.length>=4&&state.recent.slice(-4).filter(Boolean).length<=1&&state.stage>0){state.stage--;state.recent=[]}}
let recentTopics=[];
function problem(level){
 level=Math.max(0,Math.min(level,scoreCap(state.points)));
 const review=Math.max(0,level-1),stretch=Math.min(5,level+1,scoreCap(state.points));
 const slot=(state.mixIndex||0)%8;state.mixIndex=(state.mixIndex||0)+1;
 const foundation=level>=2&&slot===4;
 let tier=[review,review,level,stretch,foundation?0:review,review,level,stretch][slot];
 if((state.recoveryQuestions||0)>0){tier=foundation?0:review;state.recoveryQuestions--}
 const introductory=state.total<4&&state.points<40;if(introductory)tier=0;
 const buckets=new Map();MATH_BANK[tier].forEach((p,index)=>{if((introductory||foundation)&&(p.topic||p.q.match(/\d+/g).some(n=>Number(n)>20)))return;const topic=p.topic||'core';if(!buckets.has(topic))buckets.set(topic,[]);buckets.get(topic).push({p,index,tier})});
 state.topicDecks=state.topicDecks||{};let deck=(Array.isArray(state.topicDecks[tier])?state.topicDecks[tier]:[]).filter(k=>buckets.has(k));
 if(!deck.length){deck=[...buckets.keys()];for(let i=deck.length-1;i>0;i--){const j=int(0,i);[deck[i],deck[j]]=[deck[j],deck[i]]}}
 if(deck.length>1&&tier+':'+deck.at(-1)===recentTopics.at(-1)){const swap=deck.findIndex(t=>tier+':'+t!==recentTopics.at(-1));[deck[swap],deck[deck.length-1]]=[deck.at(-1),deck[swap]]}
 const topic=deck.pop();state.topicDecks[tier]=deck;recentTopics.push(tier+':'+topic);recentTopics=recentTopics.slice(-4);
 const pool=buckets.get(topic).sort((a,b)=>a.p.complexity-b.p.complexity),cap=tier<5?thresholds[tier+1]:thresholds[5]+3000;
 const progress=tier===0?Math.min(.35,state.points/300):Math.max(0,Math.min(1,(state.points-thresholds[tier])/(cap-thresholds[tier])));
 const high=Math.min(pool.length,Math.max(20,Math.floor(pool.length*(.15+.85*progress)))),candidates=pool.slice(Math.max(0,high-100),high);
 const unseen=candidates.filter(v=>!state.seen.includes(v.tier+':'+v.index)),available=unseen.length?unseen:candidates,entry=available[int(0,available.length-1)];
 state.seen.push(entry.tier+':'+entry.index);state.seen=state.seen.slice(-150);
 const p={...entry.p,id:entry.tier+':'+entry.index,choices:[...entry.p.choices]};for(let i=3;i>0;i--){const j=int(0,i);[p.choices[i],p.choices[j]]=[p.choices[j],p.choices[i]]}return p;
}


