function teachingHints(p){if(p.steps)return [p.steps[0].label,p.steps[Math.min(1,p.steps.length-1)].label];const n=p.q.match(/\d+/g)?.map(Number)||[];let first,second;
if(p.level===0){const [a,b]=n;if(p.q.includes('+')){first=`Start with ${a}. The + sign asks you to add ${b} more.`;second=`Split ${b} into ${Math.floor(b/10)*10} and ${b%10}. First add ${Math.floor(b/10)*10} to ${a} to get ${a+Math.floor(b/10)*10}, then add ${b%10}.`}else{first=`Start with ${a}. The minus sign asks you to take away ${b}.`;second=`Take away ${Math.floor(b/10)*10} first: ${a} − ${Math.floor(b/10)*10} = ${a-Math.floor(b/10)*10}. Now take away ${b%10} more.`}}
else if(p.level===1){const [a,b,c]=n;if(p.q.includes('÷')){first=`${a} ÷ ${b} asks how many groups of ${b} fit into ${a}.`;second=`Think “${b} times what equals ${a}?” Try groups of ${b}: ${b} × 10 = ${b*10}. Add or remove groups until you reach ${a}.`}else{first=`× means multiply: ${a} groups of ${b}. Do that before adding the extra ${c}.`;second=`${a} × ${b} = ${a*b}. Now add the remaining ${c} to ${a*b}.`}}
else if(p.level===2){const [a,b,total]=n;first=`x stands for a number you don't know yet. ${a}x means ${a} times that number. The ${b} is added afterward.`;second=`Undo the added ${b} on both sides: ${total} − ${b} = ${total-b}. Now ${a} × x = ${total-b}. Divide ${total-b} into ${a} equal groups to find x.`}
else if(p.level===3){const [sum,product]=n;first='x² means x multiplied by itself. We want the numbers that make the whole expression equal zero. This kind of problem can have two answers.';second=`Look for two positive numbers that add to ${sum} and multiply to ${product}. For example, 2 and 3 add to 5 and multiply to 6. Use that same idea with ${sum} and ${product}.`}
else if(p.level===4){const [a,b,x]=n;first=`f(x) is just a rule for turning one number into another. f(${x}) means use ${x} wherever you see x. The small ² means multiply that number by itself.`;second=`First ${x}² = ${x} × ${x} = ${x*x}. Multiply by ${a}: ${a*x*x}. Then add ${b}.`}
else if(p.q.includes('∫')){const [,x,a]=n;first='The ∫ symbol asks for the area under this line between the two given numbers. Because the line begins at zero, that area is a triangle.';second=`The triangle is ${x} units wide. At the far end, its height is ${a} × ${x} = ${a*x}. Triangle area is width × height ÷ 2.`}
else {const [a,b,x]=n;first='The little mark in f′ asks how quickly the function is changing. For a cube such as x³, the rate rule is 3 times x². A term like 4x contributes 4.';second=`For this rule, f′(x) = ${a*3}x² + ${b}. Put ${x} in place of x: first ${x}² = ${x*x}, then multiply by ${a*3}, then add ${b}.`}
return [first,second]}
