function unlockHint(verified=null){if(!run||locked)return;if(window.DailyScores?.enabled&&!verified)return onlineAction('hint',undefined,result=>unlockHint(result));if(verified)hintStep=verified.hints-1;hinted=true;challengeDirty();hintStep=Math.min(3,hintStep+1);el('hint').querySelector('span').textContent=`Hint ${hintStep}/3`;if(hintStep===3&&removedChoice===null){const index=hintEliminationIndex();if(index>=0){removedChoice=index;crossChoice(removedChoice,true)}}openTutor(current,2,null,hintStep)}
const secondHintGuides={"square-roots": ["□ × □ = number under √", "Try squaring the answer choices. Which one gives the number under the root?"], "root-expressions": ["Roots → remaining operations", "Work out each root first, then use those values in the original expression."], "simplify-radicals": ["√(a² × b) = a√b", "Find a perfect-square factor. Only that part can come out of the root."], "order-of-operations": ["Brackets → powers → × ÷ → + −", "Finish one operation at a time, keeping the rest of the expression unchanged."], "decimals": ["Align the decimal points", "Add from the right, carrying to the next column when needed."], "linear-both-sides": ["Same operation on both sides", "Subtract the smaller x term on both sides, then undo the added number."], "bracket-equations": ["Divide both sides first", "Divide by the number outside the brackets, then undo the number added to x."], "fraction-equations": ["Multiply both sides first", "Multiply by the number under the fraction bar, then isolate x."], "two-variable-substitution": ["Replace letters with their values", "Put each given value in brackets, then multiply before adding."], "general-systems": ["Eliminate one unknown", "Make one letter’s coefficients match, then subtract the equations."], "simultaneous-equations": ["Combine the equations", "Add or subtract the equations to remove one unknown, then solve for the other."], "mean": ["Mean = total ÷ count", "Add all the values, then divide by how many values there are."], "median": ["Sort → find the middle", "Write the values from smallest to largest. If two are in the middle, average them."], "range": ["Range = largest − smallest", "Identify the largest and smallest values before subtracting."], "probability": ["P = wanted outcomes ÷ all outcomes", "Count all the possible outcomes for the bottom of the fraction."], "weighted-mean": ["Σ(value × weight) ÷ Σweights", "Multiply each value by its weight, add those products, then divide by the total weight."], "partitioned-rectangle": ["Whole area = width × height", "Subtract the known section areas from the whole. For a missing width, divide its area by the shared height."], "composite-area": ["Remaining area = whole − cutout", "Calculate both rectangle areas, then subtract the missing piece."], "rectangle-diagonal": ["d² = width² + height²", "Find the blue section’s width first. Square its width and height, add, then take the square root."], "right-triangle": ["c = √(a² + b²)", "Square each of the two shorter sides, add them, then take the square root."], "triangle-angles": ["x = 180° − the known angles", "Add the two labelled angles, then subtract that sum from 180°."], "parallel-angles": ["Matching positions → equal angles", "Look at the two blue angles. They occupy the same position at the two crossings."], "percentages": ["Percent ÷ 100 × whole", "Convert the percentage into a fraction out of 100, then multiply by the whole."], "discounts": ["New price = price − discount", "Calculate the discount amount first, then subtract it from the original price."], "rectangle-area": ["Area = length × width", "Multiply the two side lengths. Area uses square units."], "circle-area": ["Area = πr²", "Square the radius first, then multiply by the given value of π."], "fractions": ["Use a common denominator", "Rewrite both fractions with the same bottom number before combining the top numbers."], "mixed-fractions": ["Mixed number → improper fraction", "Multiply the whole number by the denominator and add the numerator. Then combine the fractions."], "divide-fractions": ["a/b ÷ c/d = a/b × d/c", "Turn mixed numbers into fractions first. Flip the second fraction and multiply."], "ratios": ["Find the value of one part", "Divide by the known number of parts, then multiply by the number of parts wanted."], "expressions": ["Substitute → multiply → add", "Replace each letter with its given value in brackets before calculating."], "quadratic-formula": ["x = (−b ± √(b² − 4ac)) / (2a)", "Identify a, b and c with their signs. Work out the part under the root first."], "logarithms": ["log_b(n) = x means bˣ = n", "Ask what power of the base produces the given number."], "exponent-laws": ["aᵐ × aⁿ = aᵐ⁺ⁿ", "For the same base, add powers when multiplying and subtract powers when dividing."], "quadratic-derivative": ["d(ax² + bx + c)/dx = 2ax + b", "Apply the power rule, then substitute the requested x value."], "polynomial-integral": ["∫axⁿ dx = axⁿ⁺¹/(n+1)", "Increase each power by one and divide by the new power. For bounds, subtract the lower result from the upper."], "equal-groups": ["Total = groups × each group", "Use multiplication for a total, or division to find one group’s size."], "missing-number": ["Undo the known operation", "Use the opposite operation to isolate the missing value."], "trapezoid-area": ["Area = (a + b) × h ÷ 2", "Add the two parallel side lengths, multiply by the height, then halve."], "trigonometry": ["sin = opposite/hypotenuse", "For the marked angle, use sin, cos (adjacent/hypotenuse), or tan (opposite/adjacent) to match the given sides."]};
function secondHint(p){let guide=secondHintGuides[p.topic];if(!guide){const guides=[["Work by place value","Combine the ones, tens and hundreds separately. Keep track of carries or borrowing."],["Multiplication and division first","Complete the multiplication or division before any addition."],["Keep both sides balanced","Undo the added number on both sides, then divide both sides by the number multiplying x."],["Find a pair of factors","Look for two numbers whose sum and product match the equation."],["Substitute before calculating","Replace x with the given value in brackets, then square, multiply and add in order."],["Apply the power rule","For a derivative, multiply by the power and reduce it by one. For an integral, raise the power and divide by the new power."]];guide=guides[p.level]||guides[0]}return {html:`<div class="math-line">${guide[0]}</div>`,label:guide[1]}}
function hintCard(p,stage){if(stage<=2)return learningHint(p,stage);if(stage===3)return {html:'',label:removedChoice!==null?`The gray choice, ${p.choices[removedChoice]}, is ruled out. Choose from the remaining answers.`:'Use the earlier hints to compare the remaining answers.'};if(p.visualHint){if(stage===1)return p.visualHint;return {html:'',label:`Find the blue angle marked ${p.answer}°. The blue angle x is in the same position at the other crossing.`}}const cards=p.concepts||staticSteps(p);if(stage===1)return cards[0];if(cards.length>1)return cards[1];if(p.concepts)return staticSteps(p)[0];return {html:'',label:p.hint||'Use the rule from Hint 1 with the values in the question.'}}
