let syncQueue=Promise.resolve();
function syncScore(name){if(window.DailyScores?.enabled)return (name?window.DailyScores.rename(name):window.DailyScores.initialize()).then(()=>{profile=window.DailyScores.getProfile();return profile});syncQueue=syncQueue.catch(()=>{}).then(async()=>{const proposed=name||((profile?.name&&!/^Player [A-Z0-9]{4}$/.test(profile.name))?profile.name:randomName());const response=await fetch('/api/score',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:profile?.id,token:profile?.token,name:proposed,score:state.points,})});if(!response.ok)throw new Error('Score server unavailable');profile=await response.json();try{window.DailyStorage.setItem('daily-math-player',JSON.stringify(profile))}catch{}return profile});return syncQueue}
