el('scratchCanvas').addEventListener('pointerdown',e=>{e.preventDefault();const c=el('scratchCanvas');c.setPointerCapture(e.pointerId);const p=scratchScreen(e);if(scratchTool==='eraser')showEraserCursor(p);scratchPointers.set(e.pointerId,p);if(scratchPointers.size===2){drawingStroke=null;const [a,b]=[...scratchPointers.values()],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};scratchGesture={type:'pinch',distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y)),zoom:scratchView.zoom,anchor:scratchWorld(mid)};paintScratch();return}if(scratchPointers.size>2)return;scratchGesture={type:scratchTool==='move'?'pan':'draw',start:p,last:p,time:performance.now(),moved:false};if(scratchTool!=='move')drawingStroke={id:++strokeSerial,tool:scratchTool,color:scratchTool==='highlighter'?highlightColor:penColor,width:scratchTool==='highlighter'?highlightWidth:penWidth,points:[scratchWorld(p)],ids:[]};if(scratchTool==='eraser'){eraseWholeStrokes(scratchWorld(p),scratchWorld(p));paintScratch()}});
el('scratchCanvas').addEventListener('pointermove',e=>{if(scratchTool==='eraser')showEraserCursor(scratchScreen(e));if(!scratchPointers.has(e.pointerId)||!scratchGesture)return;const p=scratchScreen(e);if(scratchTool==='eraser')showEraserCursor(p);scratchPointers.set(e.pointerId,p);if(scratchPointers.size>=2&&scratchGesture.type==='pinch'){const[a,b]=[...scratchPointers.values()],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};scratchView.zoom=clampZoom(scratchGesture.zoom*Math.hypot(a.x-b.x,a.y-b.y)/scratchGesture.distance);scratchView.x=mid.x-scratchGesture.anchor[0]*scratchView.zoom;scratchView.y=mid.y-scratchGesture.anchor[1]*scratchView.zoom}else if(scratchGesture.type==='pan'){scratchView.x+=p.x-scratchGesture.last.x;scratchView.y+=p.y-scratchGesture.last.y;scratchGesture.last=p}else if(scratchGesture.type==='draw'&&drawingStroke){for(const sample of (e.getCoalescedEvents?.().length?e.getCoalescedEvents():[e])){const raw=scratchWorld(scratchScreen(sample)),last=drawingStroke.points.at(-1);if(drawingStroke.tool==='eraser'){eraseWholeStrokes(last,raw);drawingStroke.points.push(raw)}else if(Math.hypot(raw[0]-last[0],raw[1]-last[1])>.3/scratchView.zoom){const smooth=.65;drawingStroke.points.push([last[0]+(raw[0]-last[0])*smooth,last[1]+(raw[1]-last[1])*smooth])}}scratchGesture.moved ||= Math.hypot(p.x-scratchGesture.start.x,p.y-scratchGesture.start.y)>8}paintScratch()});
el('scratchCanvas').addEventListener('pointerleave',()=>{el('eraserCursor').hidden=true});
function finishScratch(e){if(e.pointerType==='touch')el('eraserCursor').hidden=true;if(!scratchPointers.has(e.pointerId))return;const p=scratchScreen(e),g=scratchGesture;scratchPointers.delete(e.pointerId);if(g?.type==='draw'&&drawingStroke){if(drawingStroke.tool==='eraser'){if(drawingStroke.ids.length){scratchStrokes.push({tool:'erase-strokes',ids:[...drawingStroke.ids]});scratchRedo=[]}drawingStroke=null;lastScratchTap=null;if(!scratchPointers.size)scratchGesture=null;paintScratch();return}if(g.moved)drawingStroke.points.push(scratchWorld(p));const tap=!g.moved&&performance.now()-g.time<300;if(tap&&lastScratchTap&&performance.now()-lastScratchTap.time<350&&Math.hypot(p.x-lastScratchTap.p.x,p.y-lastScratchTap.p.y)<25){if(scratchStrokes.at(-1)===lastScratchTap.stroke)scratchStrokes.pop();drawingStroke=null;lastScratchTap=null;zoomScratch(scratchView.zoom>=4?1:scratchView.zoom*1.5,p)}else{scratchStrokes.push(drawingStroke);scratchRedo=[];lastScratchTap=tap?{time:performance.now(),p,stroke:drawingStroke}:null;drawingStroke=null}}if(!scratchPointers.size)scratchGesture=null;else scratchGesture={type:'wait'};paintScratch()}
el('scratchCanvas').addEventListener('pointerup',finishScratch);el('scratchCanvas').addEventListener('pointercancel',e=>{scratchPointers.delete(e.pointerId);drawingStroke=null;if(!scratchPointers.size)scratchGesture=null;paintScratch()});el('scratchCanvas').addEventListener('wheel',e=>{e.preventDefault();zoomScratch(scratchView.zoom*Math.exp(-e.deltaY*.002),scratchScreen(e))},{passive:false});

const originalDiagramMarkup=new WeakMap();
function fitBoardDiagram(){const stage=document.querySelector('.diagram-stage');if(!stage)return;const svg=stage.querySelector('svg');if(!svg)return;if(!originalDiagramMarkup.has(svg))originalDiagramMarkup.set(svg,{html:svg.innerHTML,view:svg.getAttribute('viewBox')});const original=originalDiagramMarkup.get(svg);svg.innerHTML=original.html;svg.setAttribute('viewBox',original.view);const dimension=svg.classList.contains('dimension-diagram');if(dimension){const rect=stage.getBoundingClientRect(),height=Math.max(245,Math.min(420,rect.height/Math.max(1,rect.width)*370)),bottom=height-67;const y=v=>v<=78?v:v<=178?78+(v-78)*(bottom-78)/100:v+(bottom-178);svg.setAttribute('viewBox',`0 0 370 ${height}`);svg.querySelectorAll('path').forEach(path=>{path.setAttribute('d',path.getAttribute('d').replace(/([MLHVmlhvZz])([^MLHVmlhvZz]*)/g,(all,command,args)=>{if(!['M','L','V'].includes(command))return all;const values=args.trim().split(/[ ,]+/).filter(Boolean).map(Number);return command+values.map((v,i)=>command==='V'||i%2===1?Number(y(v).toFixed(2)):v).join(' ')}))});svg.querySelectorAll('rect').forEach(node=>{const top=Number(node.getAttribute('y')||0),h=Number(node.getAttribute('height')||0);node.setAttribute('y',y(top));node.setAttribute('height',y(top+h)-y(top))});svg.querySelectorAll('text').forEach(node=>{if(node.hasAttribute('y'))node.setAttribute('y',y(Number(node.getAttribute('y'))));const transform=node.getAttribute('transform');if(transform)node.setAttribute('transform',transform.replace(/rotate\(([-\d.]+) ([-\d.]+) ([-\d.]+)\)/,(_,angle,x,cy)=>`rotate(${angle} ${x} ${y(Number(cy))})`))})}svg.querySelectorAll('text').forEach(node=>{const size=Number(node.getAttribute('font-size')||node.closest('g[font-size]')?.getAttribute('font-size')||17);if(size<=11)return;const larger=dimension?(size>=30?size:size>=25?size+2:size+3):size+2;node.style.fontSize=larger+'px'})}
if(typeof ResizeObserver!=='undefined')new ResizeObserver(fitBoardDiagram).observe(el('board'));

document.addEventListener('keydown',e=>{if(!el('scratchDialog').open||!(e.ctrlKey||e.metaKey))return;const k=e.key.toLowerCase();if(k==='z'||k==='y'){e.preventDefault();if(k==='y'||e.shiftKey)redoScratch();else undoScratch()}});if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>{if(el('scratchDialog').open)paintScratch()}).observe(el('scratchCanvas'));

function calculate(text){const source=text.replace(/\s/g,'').replaceAll('×','*').replaceAll('÷','/');if(!source||source.length>80||/[^\d.+\-*/()]/.test(source))throw Error('Invalid');const tokens=source.match(/(?:\d+(?:\.\d*)?|\.\d+)|[()+\-*/]/g)||[];let i=0;function atom(){if(tokens[i]==='+'){i++;return atom()}if(tokens[i]==='-'){i++;return -atom()}if(tokens[i]==='('){i++;const v=sum();if(tokens[i++]!==')')throw Error('Bracket');return v}const t=tokens[i++];if(!t||!/^\d|^\.\d/.test(t))throw Error('Number');return Number(t)}function product(){let v=atom();while(tokens[i]==='*'||tokens[i]==='/'){const op=tokens[i++],right=atom();v=op==='*'?v*right:v/right}return v}function sum(){let v=product();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++],right=product();v=op==='+'?v+right:v-right}return v}const result=sum();if(i!==tokens.length||!Number.isFinite(result))throw Error('Invalid');return Number(result.toPrecision(12)).toString()}
el('calcKeys').innerHTML=['C','(',')','⌫','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','=','+'].map(k=>`<button class="chunk ${k==='='?'blue':''}" data-key="${k}">${k}</button>`).join('');
function calcKey(k){const input=el('calcDisplay');if(k==='C')input.value='';else if(k==='⌫')input.value=input.value.slice(0,-1);else if(k==='='){try{input.value=calculate(input.value)}catch{input.value='Check calculation'}}else{if(input.value==='Check calculation')input.value='';if(input.value.length<80)input.value+=k==='−'?'-':k}}
document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>calcKey(b.dataset.key));el('calcDisplay').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();calcKey('=')}});function openCalculator(){el('calcQuestion').textContent=current?.q||'';el('closeCalc').textContent=el('scratchDialog').open?'Back to whiteboard':'Done';el('calcDialog').showModal()}el('calcButton').onclick=openCalculator;el('scratchCalcButton').onclick=openCalculator;el('closeCalc').onclick=()=>el('calcDialog').close();

document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(run&&!locked&&!e.repeat&&['1','2','3','4'].includes(e.key)){e.preventDefault();sound('tap');selectAnswer(Number(e.key)-1)}else if(run&&!locked&&e.key==='Enter'&&!e.repeat&&(e.target===document.body||e.target?.matches?.('[data-choice]'))){e.preventDefault();sound('tap');confirmAnswer()}});home();

// A tap outside a panel returns to the surface beneath it; dragging out does not.
function bindOutsideDismiss(dialog,close){let pressedOutside=false;const outside=e=>{const r=dialog.getBoundingClientRect();return e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)};dialog.addEventListener('pointerdown',e=>{pressedOutside=outside(e)});dialog.addEventListener('pointercancel',()=>{pressedOutside=false});dialog.addEventListener('click',e=>{if(pressedOutside&&outside(e)&&dialog.open)close();pressedOutside=false});dialog.addEventListener('close',()=>{pressedOutside=false})}
for(const id of ['settingsDialog','leaderboardDialog','streakDialog','scratchDialog','calcDialog','nicknameDialog'])bindOutsideDismiss(el(id),()=>el(id).close());bindOutsideDismiss(el('tutorDialog'),closeTutor);bindOutsideDismiss(el('resultDialog'),dismissResult);

window.DailyPlatform?.onChange(info=>{document.querySelectorAll('.game,body > dialog').forEach(node=>node.inert=info.paused||advancing);const pause=el('platformPause');if(pause){pause.hidden=!info.paused;pause.textContent=info.adState==='loading'?'Ad break…':'Paused'}if(!info.audioAllowed){el('bgMusic').pause();window.stopDailyFeedback?.()}else if(run){playMusic();audioCtx?.resume().catch(()=>{})}});
if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>requestAnimationFrame(()=>window.DailyPlatform?.ready()));else window.DailyPlatform?.ready();

function networkMessage(message){el('networkStatus').textContent=message;el('networkStatus').hidden=!message}
function onlineControls(busy){networkBusy=busy;for(const id of ['confirmAnswer','hint','skip','nextHint']){const node=el(id);if(node)node.disabled=busy||locked||(id==='confirmAnswer'&&selectedAnswer===null)}}
function restoreOnlineRound(active){const [tier,index]=active.questionId.split(':').map(Number),saved=MATH_BANK[tier]?.[index];if(!saved)throw Error('This question needs a game update.');next({...saved,id:active.questionId,choices:[...saved.choices]});hintStep=active.hints;hinted=hintStep>0;mistakes=active.mistakes;for(const choice of active.excluded){const i=current.choices.indexOf(choice);if(i>=0)crossChoice(i,false,0)}if(hintStep===3){removedChoice=hintEliminationIndex();if(removedChoice>=0)crossChoice(removedChoice,true)}if(hintStep)el('hint').querySelector('span').textContent=`Hint ${hintStep}/3`;if(mistakes)state.streak=0;stats()}
async function beginOnline(){if(networkBusy)return;networkBusy=true;networkMessage('Connecting…');try{const data=await window.DailyScores.initialize();profile=data.player;state.points=data.player.score;state.stage=Math.min(state.stage,scoreCap(state.points));run={index:0,correct:0,skipped:0,points:0};playMusic();if(data.activeRound)restoreOnlineRound(data.activeRound);else next();save();stats();networkMessage('')}catch(error){const safeScoreError=error?.name==='DailyScoreError'&&typeof error.message==='string';networkMessage(safeScoreError?error.message:'Could not start this question. Tap Play to try again.');console.warn('Daily Math start failed',{name:error?.name||'Error',code:typeof error?.code==='string'?error.code:'game_start_failed'});}finally{networkBusy=false}}
async function onlineAction(type,choice,apply){if(networkBusy)return;onlineControls(true);networkMessage('Saving…');try{await window.DailyScores.startRound(current.id);const result=await window.DailyScores.act(type,choice);profile=result.player;networkMessage('');networkBusy=false;apply(result);state.points=result.player.score;save();stats()}catch(error){if(error.code==='active_round'&&error.activeRound){if(error.player){profile=error.player;state.points=profile.score}restoreOnlineRound(error.activeRound);networkMessage('Your unfinished question is restored.')}else networkMessage(error.code==='rate_limited'?'Please wait a minute, then try again.':'Could not save. Try that button again.')}finally{onlineControls(false)}}

window.DailyStorage?.onChange?.(status=>{el('storage').textContent=status==='session-only'?'Cloud save unavailable — this visit only.':status==='save-error'?'Progress could not save. Keep this game open.':''});

// Optional challenge feature leaves ordinary adaptive selection and scores intact.
function challengeState(){if(!window.DailyAgeChallenge)return null;return state.challenge=window.DailyAgeChallenge.normalize(state.challenge,state.points)}
function updateChallengeUI(){const c=challengeState();if(!c)return;const d=window.DailyAgeChallenge.describe(c);el('challengeLabel').textContent=d.label;el('challengeTarget').textContent=d.target;el('challengeFill').style.width=(d.progress*100)+'%';el('challengeButton').setAttribute('aria-label',d.label+' · '+d.target);el('challengeSummary').textContent=d.summary;el('challengeTopics').textContent=d.topics;el('challengeStart').disabled=!d.ready;el('challengeStart').textContent=d.ready?(c.lastResult&&!c.lastResult.passed?'Try again':'Start challenge'):'Not ready yet';el('challengeTitle').textContent=d.age?`Age ${d.age} challenge`:'Challenges cleared'}
function challengeNext(){const c=challengeState();return c?window.DailyAgeChallenge.next(c,MATH_BANK):null}
function challengeAttach(p){const c=challengeState();return c?window.DailyAgeChallenge.attach(c,p):p}
function challengeDirty(){const c=challengeState();if(c){window.DailyAgeChallenge.dirty(c,current);save()}}
function challengeComplete(clean){const c=challengeState();return c?window.DailyAgeChallenge.complete(c,current,clean):null}
if(window.DailyAgeChallenge){el('challengeButton').onclick=()=>{updateChallengeUI();el('challengeDialog').showModal()};el('closeChallenge').onclick=()=>el('challengeDialog').close();el('challengeStart').onclick=()=>{if(networkBusy||advancing)return;const c=challengeState();if(!window.DailyAgeChallenge.queue(c))return;save();stats();el('challengeDialog').close();if(!run)begin()};bindOutsideDismiss(el('challengeDialog'),()=>el('challengeDialog').close());updateChallengeUI()}
